import type { Invocation } from "./control-types";
import type { WorkRef } from "./types";
/** Journal-owned fields: created and persisted BEFORE invoke, never generated by adapter. */
export interface NativeControlInvocation extends Invocation {
  native_client_message_id: string;
  native_interface_version: string;
}
export interface NativeMetadata { work: WorkRef; cwd: string; version: string; epoch: string }
export type ValidateNativeMetadata = (invocation: Invocation, metadata: NativeMetadata) => boolean | Promise<boolean>;
export interface NativeFrame { id?: number | string; method?: string; params?: any; result?: any; error?: { code?: number; message?: string } }
export interface NativeSocket {
  on(event: string, listener: (...args: any[]) => void): unknown;
  send(data: string): void;
  close(): void;
}
export interface ListenerEvidence { socket: string; executable: string; pid: number; version: string; identity: string }
export type NativeMethod = "initialize" | "thread/loaded/list" | "thread/read" | "thread/resume" | "thread/turns/list" | "turn/start" | "turn/steer";
